import { expect, type Page, test } from "./base";
import { createAccount, findProductCard, signIn } from "./helpers";

// Fixture products (e2e/fixtures/products.ts, imported by global-setup.ts); ids
// are generated by the import, so each test finds its product through the
// catalog search on /home. Each test reviews with its own fresh account.
const KETTLE = {
  query: "Chaleira",
  title: "Chaleira Elétrica Inox 1,7L",
  price: "R$ 3.350,90",
};
const MIXER = { query: "Mixer", title: "Mixer de Mão 3 em 1" };
const DUNE = { query: "Duna", title: "Duna Edição Especial" };

const FEEDBACK_URL = /\/products\/[A-Za-z0-9_-]+\/feedback$/;

// Searches the catalog and follows "Give feedback" on the product's card.
async function openFeedbackPage(
  page: Page,
  product: { query: string; title: string },
) {
  const card = await findProductCard(page, product);
  await card.getByRole("link", { name: /Give feedback/ }).click();
  await expect(page).toHaveURL(FEEDBACK_URL);
  await expect(page.getByTestId("product-summary")).toContainText(
    product.title,
  );
  return new URL(page.url()).pathname.split("/")[2];
}

test.describe("feedback", () => {
  test("/feedback/new now leads to the catalog", async ({ page, request }) => {
    await signIn(page, await createAccount(request));
    await page.goto("/feedback/new");
    await expect(page).toHaveURL("/home");
  });

  test("anonymous visit to a feedback page redirects to sign-in", async ({
    page,
  }) => {
    await page.goto("/products/V1StGXR8_Z5jdHi6B-myT/feedback");
    await expect(page).toHaveURL("/auth/sign-in");
  });

  test("an unknown product shows the 404 page with a link to /home", async ({
    page,
    request,
  }) => {
    await signIn(page, await createAccount(request));
    await page.goto("/products/unknown/feedback");

    await expect(
      page.getByRole("heading", { level: 1, name: "Product not found" }),
    ).toBeVisible();
    await page.getByRole("link", { name: "Go to the catalog" }).click();
    await expect(page).toHaveURL("/home");
  });

  test("review a catalog product: live slip, post, /me, then blocked", async ({
    page,
    request,
  }) => {
    const account = await createAccount(request, {
      firstName: "Grace",
      lastName: "Hopper",
    });
    await signIn(page, account);
    const productId = await openFeedbackPage(page, KETTLE);

    // The product: title linking to Amazon in a new tab, and the current price
    const summary = page.getByTestId("product-summary");
    const amazonLink = summary.getByRole("link", { name: /Chaleira/ });
    await expect(amazonLink).toHaveAttribute("target", "_blank");
    await expect(amazonLink).toHaveAttribute(
      "rel",
      "noopener noreferrer nofollow",
    );
    await expect(amazonLink).toHaveAttribute("href", /amazon\.com\.br\/dp\//);
    await expect(summary).toContainText(KETTLE.price);

    // The slip prints the product title, the stars and the author while typing
    const preview = page.getByTestId("slip-preview");
    await expect(preview).toContainText(KETTLE.title);
    await expect(preview).toContainText("Review by Grace H.");

    await page.getByRole("radio", { name: "4 stars" }).check({ force: true });
    await expect(
      preview.locator('[aria-label="4 out of 5 stars"]'),
    ).toBeVisible();

    const comment = "Boils fast and the lid does not drip.";
    await page.getByLabel("Comment").fill(comment);
    await expect(preview).toContainText(comment);
    await expect(
      page.getByText(`${comment.length} of 2000 characters`),
    ).toBeVisible();

    await page.getByRole("button", { name: "Post feedback" }).click();
    await expect(page.getByText("Feedback posted")).toBeVisible();
    await expect(page).toHaveURL("/me");

    // Newest first, with the product image and title
    const first = page
      .getByTestId("recent-feedback")
      .getByRole("listitem")
      .first();
    await expect(first).toContainText(KETTLE.title);
    await expect(first).toContainText(comment);
    await expect(first.locator("img")).toBeVisible();

    // The same product cannot be reviewed twice: page message ...
    await page.goto(`/products/${productId}/feedback`);
    await expect(
      page.getByRole("heading", {
        level: 1,
        name: "You already reviewed this product",
      }),
    ).toBeVisible();
    await expect(
      page.getByRole("button", { name: "Post feedback" }),
    ).toHaveCount(0);
    await page.getByRole("link", { name: "See your reviews" }).click();
    await expect(page).toHaveURL("/me");

    // ... and 409 from the API (same session cookie)
    const response = await page.request.post("/api/v1/feedback", {
      data: { productId, rating: 5, comment: "Trying to review it again." },
    });
    expect(response.status()).toBe(409);
    expect(await response.json()).toEqual({
      error: "You already reviewed this product",
    });
  });

  test("an empty submit shows the field errors and rating works with the keyboard", async ({
    page,
    request,
  }) => {
    await signIn(page, await createAccount(request));
    await openFeedbackPage(page, MIXER);

    await page.getByRole("button", { name: "Post feedback" }).click();
    await expect(page.getByText("Choose a rating")).toBeVisible();
    await expect(
      page.getByText("Comment must have at least 10 characters"),
    ).toBeVisible();

    // Tab into the group from the product link, select the first star, then
    // move with the arrows
    await page
      .getByTestId("product-summary")
      .getByRole("link", { name: /Mixer/ })
      .focus();
    await page.keyboard.press("Tab");
    await expect(page.getByRole("radio", { name: "1 star" })).toBeFocused();
    await page.keyboard.press("Space");
    await page.keyboard.press("ArrowRight");
    await page.keyboard.press("ArrowRight");
    await expect(page.getByRole("radio", { name: "3 stars" })).toBeChecked();
    await expect(page.getByText("Choose a rating")).toBeHidden();
    await expect(
      page
        .getByTestId("slip-preview")
        .locator('[aria-label="3 out of 5 stars"]'),
    ).toBeVisible();
  });

  test("a comment with markup is shown as plain text", async ({
    page,
    request,
  }) => {
    await signIn(page, await createAccount(request));
    await openFeedbackPage(page, DUNE);

    const comment = "<script>window.__xss = true</script> works fine";
    await page.getByRole("radio", { name: "5 stars" }).check({ force: true });
    await page.getByLabel("Comment").fill(comment);
    await page.getByRole("button", { name: "Post feedback" }).click();
    await expect(page).toHaveURL("/me");

    const first = page
      .getByTestId("recent-feedback")
      .getByRole("listitem")
      .first();
    await expect(first).toContainText(DUNE.title);
    await expect(first).toContainText(comment);
    expect(await page.evaluate(() => "__xss" in window)).toBe(false);
  });
});
